			for (let i = 0, len = selections.length; i < len; i++) {
				const selection = selections[i];
				let effectiveClose = autoClosingPair.close;
				try {
					const position = selection.getPosition();
					const lineText = model.getLineContent(position.lineNumber);
					const afterText = lineText.substr(position.column - 1, effectiveClose.length);
					let overlap = 0;
					for (let k = Math.min(effectiveClose.length, afterText.length); k >= 1; k--) {
						if (afterText.substr(0, k) === effectiveClose.substr(effectiveClose.length - k)) {
							overlap = k;
							break;
						}
					}
					if (overlap > 0) {
						effectiveClose = effectiveClose.substr(0, effectiveClose.length - overlap);
					}
				} catch (e) {
					// ignore and use full close sequence
				}
				commands[i] = new TypeWithAutoClosingCommand(selection, ch, insertOpenCharacter, effectiveClose);

